import pandas as pd, numpy as np
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
P={}; R={}
for s in U:
 x=pd.read_csv('../persistent/stock_data/'+s+'.csv'); x['date']=pd.to_datetime(x.date); x=x.sort_values('date').set_index('date'); p=x.close.astype(float).loc[:'2026-07-15']; P[s]=p; R[s]=p.pct_change()
px=pd.concat(P,axis=1,sort=True); r=pd.concat(R,axis=1,sort=True)
rv5=r.rolling(5,min_periods=5).std(); rv40=r.rolling(40,min_periods=30).std(); f=-(rv5/rv40)
for h in [1,5,10]:
 fr=pd.concat({s:P[s].shift(-h)/P[s]-1 for s in U},axis=1,sort=True); vals=[]; dates=[]; ns=[]
 for dt in f.index:
  a=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
  if len(a)>=8:
   vals.append(a.iloc[:,0].corr(a.iloc[:,1],method='spearman')); dates.append(dt); ns.append(len(a))
 z=pd.Series(vals,index=pd.to_datetime(dates)).dropna(); print('h',h,'dates',len(z),'avgN',round(np.mean(ns),2),'IC',round(z.mean(),6),'ICIR',round(z.mean()/z.std(),6),'hit',round((z>0).mean(),4))
 if h==1:
  for yr,g in z.groupby(z.index.year): print('regime',yr,'IC',round(g.mean(),5),'n',len(g))
rr=f.rank(axis=1,pct=True); print('coverage',round(f.notna().sum().sum()/f.size,4),'rank turnover',round(rr.diff().abs().mean(axis=1).mean(),4))

import pandas as pd, numpy as np, glob, os
from scipy.stats import spearmanr
files=glob.glob('../persistent/stock_data/*.csv')
prices={}
for f in files:
 s=os.path.basename(f).replace('.csv',''); d=pd.read_csv(f); d['date']=pd.to_datetime(d['date']); d=d.sort_values('date').set_index('date'); prices[s]=d
# efficiency ratio: directional displacement / path length, signed by trend
rows=[]
for s,d in prices.items():
 r=d['close'].pct_change(); disp=d['close'].pct_change(20).abs(); path=r.abs().rolling(20).sum(); trend=np.sign(d['close'].pct_change(20)); fac=(disp/path*trend).replace([np.inf,-np.inf],np.nan); fwd=d['close'].pct_change().shift(-1)
 x=pd.DataFrame({'factor':fac,'fwd':fwd,'asset':s}); x['date']=x.index; rows.append(x)
z=pd.concat(rows).dropna(subset=['factor','fwd'])
ics=[]; turnovers=[]; counts=[]
for dt,g in z.groupby('date'):
 if len(g)>=8 and g.factor.nunique()>2 and g.fwd.nunique()>2:
  ics.append(spearmanr(g.factor,g.fwd).statistic); counts.append(len(g))
# rank turnover among consecutive dates, average overlap
rank=z.pivot(index='date',columns='asset',values='factor').rank(axis=1,pct=True)
turn=(rank.diff().abs().mean(axis=1)).dropna().mean()
a=np.array(ics)
print('dates',len(a),'avg_names',np.mean(counts),'coverage',len(z)/sum(len(d) for d in prices.values()),'IC',a.mean(),'ICIR',a.mean()/a.std(ddof=1),'hit',(a>0).mean(),'turnover',turn)
for h in [5,10]:
 rr=[]
 for s,d in prices.items():
  f=d['close'].pct_change(20).abs()/d['close'].pct_change().abs().rolling(20).sum()*np.sign(d['close'].pct_change(20)); fw=d['close'].pct_change(h).shift(-h); q=pd.DataFrame({'f':f,'y':fw}).dropna(); q['date']=q.index; rr.append(q)
 q=pd.concat(rr); vals=[]
 for dt,g in q.groupby('date'):
  if len(g)>=8: vals.append(spearmanr(g.f,g.y).statistic)
 vals=np.array(vals); print(h,'d IC',vals.mean(),'ICIR',vals.mean()/vals.std(ddof=1),'dates',len(vals))
# annual
for yr,g in z.assign(year=z.date.dt.year).groupby('year'):
 vals=[]
 for dt,x in g.groupby('date'):
  if len(x)>=8: vals.append(spearmanr(x.factor,x.fwd).statistic)
 print(yr,len(vals),round(np.nanmean(vals),4),round(np.nanmean(vals)/np.nanstd(vals,ddof=1),4))

import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data, get_index_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
# low-vol trend: negative 20d realized vol, with volatility-of-vol stabilization
frames={}
for s in U:
 d=get_stock_daily_data(s,2500)
 if d is None: d=get_index_daily_data(s,2500)
 if d is not None and len(d):
  d=d[['date','close']].copy(); d['r']=d.close.pct_change(); frames[s]=d.set_index('date')
# date aligned factor known at t and forward returns t+1,t+5,t+10
all_dates=sorted(set().union(*[set(x.index) for x in frames.values()]))
rows={h:[] for h in [1,5,10]}; daily=[]
for dt in all_dates:
 vals=[]; fwd={h:[] for h in [1,5,10]}
 for s,d in frames.items():
  if dt not in d.index: continue
  ix=d.index.get_loc(dt)
  if ix<40: continue
  r=d.r.iloc[:ix+1]
  if r.iloc[-20:].isna().any() or ix+10>=len(d): continue
  vol=r.iloc[-20:].std()
  vv=r.iloc[-40:].rolling(10).std().iloc[-1]
  if not np.isfinite(vol) or not np.isfinite(vv): continue
  # prefer stable low realized volatility, mildly reward recent vol decline
  fac=-np.log(vol+1e-8) - 0.25*np.log(vv+1e-8)
  vals.append((s,fac))
  for h in [1,5,10]: fwd[h].append(d.close.iloc[ix+h]/d.close.iloc[ix]-1)
 if len(vals)>=8:
  x=np.array([z[1] for z in vals]);
  for h in [1,5,10]:
   y=np.array(fwd[h]); rows[h].append(np.corrcoef(x,y)[0,1])
  daily.append((dt,len(vals)))
def stats(a):
 a=np.array(a); a=a[np.isfinite(a)]; return len(a),float(a.mean()),float(a.mean()/a.std(ddof=1)) if len(a)>1 and a.std(ddof=1)>0 else 0,float((a>0).mean())
print('dates',len(daily),'avg_names',np.mean([n for _,n in daily]))
for h in [1,5,10]: print(h,stats(rows[h]))
for y in range(2020,2027):
 z=[rows[1][i] for i,(dt,n) in enumerate(daily) if pd.Timestamp(dt).year==y]
 print('regime',y,stats(z))
print('coverage',sum(n for _,n in daily)/(len(daily)*15))

import pandas as pd, numpy as np
from scipy.stats import spearmanr
base='../persistent'; syms=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
px={s:pd.read_csv(f'{base}/stock_data/{s}.csv',parse_dates=['date']).set_index('date').close for s in syms}
vix=pd.read_csv(f'{base}/index_data/VIX.csv',parse_dates=['date']).set_index('date').close
r=pd.DataFrame(px).pct_change(); vr=vix.pct_change(); rows=[]
for i,d in enumerate(r.index):
 if d not in vr.index or i+10>=len(r): continue
 hist=r.iloc[:i+1].tail(120); vh=vr.reindex(hist.index)
 if len(hist)<80 or vh.notna().sum()<60: continue
 shock=vh>=vh.quantile(.80)
 if shock.sum()<8: continue
 f=hist.loc[shock].mean()*1e3 + .25*hist.tail(20).mean()*1e3
 for s in syms:
  if pd.notna(f.get(s)): rows.append((d,s,f[s]))
df=pd.DataFrame(rows,columns=['date','sym','factor'])
def run(h):
 vals=[]
 for d,g in df.groupby('date'):
  i=r.index.get_loc(d); y=r.iloc[i+1:i+1+h].sum().reindex(g.sym).values
  z=pd.DataFrame({'x':g.set_index('sym').factor,'y':y},index=g.sym).dropna()
  if len(z)>=8: vals.append(spearmanr(z.x,z.y).statistic)
 a=np.array(vals); return len(a),np.nanmean(a),np.nanmean(a)/np.nanstd(a,ddof=1),(a>0).mean()
for h in [1,5,10]: print(h,*(round(x,5) if isinstance(x,float) else x for x in run(h)))
print('dates',df.date.nunique(),'avg names',round(df.groupby('date').size().mean(),2),'coverage',round(len(df)/(r.shape[0]*15),4))
for yr,g in df.groupby(df.date.dt.year):
 vals=[]
 for d,z in g.groupby('date'):
  i=r.index.get_loc(d); y=r.iloc[i+1:i+2].sum().reindex(z.sym).values
  zz=pd.DataFrame({'x':z.set_index('sym').factor,'y':y}).dropna()
  if len(zz)>=8: vals.append(spearmanr(zz.x,zz.y).statistic)
 print(yr,len(vals),round(np.nanmean(vals),4),round(np.nanmean(vals)/np.nanstd(vals,ddof=1),4))

